   if(['teamanalytics','lineups','rotation'].includes(page))loadTeamRoster(teamA);
   if(page==='betlab'||page==='playerprops'||page==='rotation'||page==='lineups'||page==='statlab')loadAverages(0);
  if(page==='compare')loadAverages(0);
